module.exports = roundDecimal;

function roundDecimal(input, places) {
  if (typeof input !== 'string') throw new Error('Invalid input');
  if (typeof places !== 'number' || !Number.isInteger(places) || places < 0 || places > 6) {
    throw new Error('Invalid places');
  }
  if (!/^[+-]?\d+(?:\.\d+)?$/.test(input)) throw new Error('Invalid input');

  let negative = false;
  let intStr = input;
  if (input[0] === '+' || input[0] === '-') {
    if (input[0] === '-') negative = true;
    intStr = input.slice(1);
  }

  let intPart = intStr;
  let fracPart = '';
  const dot = intStr.indexOf('.');
  if (dot !== -1) {
    intPart = intStr.slice(0, dot);
    fracPart = intStr.slice(dot + 1);
  }

  const intClean = intPart.replace(/^0+/, '') || '0';

  const kept = (fracPart + '000000').slice(0, places);
  const dropped = fracPart.slice(places);

  let roundUp = false;
  if (dropped.length > 0) {
    const first = Number(dropped[0]);
    if (first > 5) {
      roundUp = true;
    } else if (first === 5) {
      const rest = dropped.slice(1);
      if (rest.length > 0 && /[1-9]/.test(rest)) {
        roundUp = true;
      } else {
        let lastDigitChar;
        if (places > 0) {
          lastDigitChar = kept[places - 1];
        } else {
          lastDigitChar = intClean[intClean.length - 1];
        }
        const lastDigit = Number(lastDigitChar);
        if (lastDigit % 2 !== 0) roundUp = true;
      }
    }
  }

  const scale = 10n ** BigInt(places);
  const truncatedScaled = BigInt(intClean) * scale + BigInt(kept || '0');
  let finalScaled = truncatedScaled;
  if (roundUp) finalScaled += 1n;

  const integerPartResult = finalScaled / scale;
  const fracPartNum = finalScaled % scale;

  let absResult;
  if (places > 0) {
    const fracStrFinal = fracPartNum.toString().padStart(places, '0');
    absResult = integerPartResult.toString() + '.' + fracStrFinal;
  } else {
    absResult = integerPartResult.toString();
  }

  if (negative && finalScaled !== 0n) {
    return '-' + absResult;
  }
  return absResult;
}
